declare(strict_types=1);require_once __DIR__.'/_bootstrap.php';$product=null;if(!empty($_GET['id'])){$product=ProductRepository::findById($db,(int)$_GET['id']);if(!$product){http_response_code(404);exit('Producto no encontrado');}}adminStart($product?'Editar producto':'Nuevo producto');?><form class="panel form-grid" method="post" action="/admin/guardar-producto.php"><input type="hidden" name="csrf" value="<?=Security::e(Security::csrfToken())?>"><input type="hidden" name="id" value="<?=(int)($product['id']??0)?>"><div class="field"><label>Nombre</label><input name="nombre" required value="<?=Security::e($product['nombre']??'')?>"></div><div class="field"><label>Slug</label><input name="slug" value="<?=Security::e($product['slug']??'')?>" placeholder="se genera del nombre"></div><div class="field"><label>Precio MXN</label><input type="number" step="0.01" min="0" name="precio" required value="<?=Security::e((string)($product['precio']??''))?>"></div><div class="field"><label>Stock</label><input type="number" min="0" name="stock" required value="<?=Security::e((string)($product['stock']??'0'))?>"></div><div class="field full"><label>URL de foto</label><input type="url" name="imagen_url" value="<?=Security::e($product['imagen_url']??'')?>"></div><div class="field full"><label>Descripción</label><textarea name="descripcion"><?=Security::e($product['descripcion']??'')?></textarea></div><div class="field"><label><input type="checkbox" name="activo" value="1" <?=!isset($product['activo'])||(int)$product['activo']?'checked':''?>> Publicado</label></div><div class="field"><label><input type="checkbox" name="destacado" value="1" <?=!empty($product['destacado'])?'checked':''?>> Destacado</label></div><div class="field full"><button class="btn" type="submit">Guardar producto</button></div></form><?php adminEnd();?>
